//! Файл: settings/catalog/sizing.rs
//! Что делает: настройки задачи t159 (решения 343–345, ревью t159) — параметры-числа подбора объёма без потолка
//! прибыли: точки выше наибольшего объёма бисекции (участки допустимости без формулы), общий предел изломов пулов DEX
//! на кандидата, мягкий срок подбора. Порог % как ограничение (342) и участки по стакану B (343) — в логике, без
//! выключателя (ревью t159). Все необязательные: не заданы — этой части нет. Значений нет.
//! Отдельный файл: base.rs и cpu.rs — общие части каталога (не раздуваем).
//! Кто вызывает: settings/catalog/mod.rs.
//! От чего зависит: settings/catalog/mod.rs (короткая запись d и наборы областей).
//! Настройки: это и есть их список (зеркало docs/SETTINGS.md, раздел «Подбор объёма»).

use super::{G, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Настройки решений 343–345. Порядок — как в docs/SETTINGS.md.
#[rustfmt::skip]
pub static SIZING: &[SettingDef] = &[
    d("Подбор объёма", "size.scan_above_pct", K::Decimal, L::Positive, "% от наибольшего объёма", G, "Решение 343 (ревью t159): допустимые объёмы ВЫШЕ наибольшего объёма бисекции — для немонотонностей без формулы (у направления есть DEX: исполнимость сплита на продаже, бюджет умного маршрута на покупке). size.grid_points равномерных точек от наибольшего объёма бисекции до него + этот %. Не считаются, если ближайший объём выше — «вложение больше бюджета», а покупка на бирже (бюджет монотонен). Концы участков по minNotional / maxNotional стакана B считаются всегда (точная формула, в логике). Цена — до size.grid_points расчётов на кандидата (в пределе size.max_evals). Не задана — выше не ищем. Необязательна").optional(),
    d("Подбор объёма", "size.pool_breaks_max", K::Integer, L::Positive, "изломов на кандидата", G, "Решение 344 (ревью t159): сколько изломов кривых пулов DEX наибольшим числом на кандидата — только пулы маршрута лучшего объёма (доли сплита, налог монеты, крючок учтены адаптером; пересечения тиков V3 / Infinity CL / Uniswap V4, границы бинов Infinity Bin / Liquidity Book, точки лесенки WooFi / Metric / iZiSwap), в отрезке бисекции, ближайшие к лучшему объёму. Считаются ПОСЛЕ обычного подбора (не вытесняют сетку и уточнение), по две точки (шаг до и после) + уточнение пиков на них. Цена — до 2 × значение + пики × (2 × size.refine_steps + 3) расчётов (в пределе size.max_evals). Не задана — без изломов DEX. Необязательна").optional(),
    d("Подбор объёма", "size.soft_deadline_pct", K::Decimal, L::PercentOpen, "% срока", G, "Решение 345 (ревью t159): мягкий срок подбора объёма — доля общего срока profit.calc_timeout_ms; только у расчёта кандидата и теневого расчёта (где общий срок есть), не в предпроверке и не в refit. Действует после границ и только когда уже посчитан объём, проходящий оба порога: тогда новых точек нет, итог — лучший проходящий, дальше финальная котировка (кандидат не теряется отказом по общему сроку). Проходящего нет — подбор идёт дальше, как без настройки. Не задана или не задан profit.calc_timeout_ms — как раньше. Необязательна").optional(),
];
